<script setup lang="ts">
import { onMounted,ref } from 'vue';import Button from 'primevue/button';import InputText from 'primevue/inputtext';import Textarea from 'primevue/textarea';import ToggleSwitch from 'primevue/toggleswitch'
import { deleteMedia,getAdminDocumentForm,saveAdminDocumentForm,uploadMedia,type AdminDocumentForm,type MediaItem } from '@/api/admin'
const props=defineProps<{token:string;id:number|null}>();const emit=defineEmits<{saved:[];cancel:[]}>();const form=ref<AdminDocumentForm>({title:'',description:'',fileMediaId:0,displayFileType:'',displayFileSize:'',position:0,isPublished:false});const file=ref<MediaItem|null>(null);const input=ref<HTMLInputElement|null>(null);const loading=ref(false);const error=ref('');const uploaded=new Set<number>();let original:number|null=null
function readable(bytes:number){if(bytes<1024)return `${bytes} Б`;if(bytes<1048576)return `${Math.round(bytes/1024)} КБ`;return `${(bytes/1048576).toFixed(1).replace('.',',')} МБ`}
onMounted(async()=>{if(!props.id)return;loading.value=true;try{form.value=await getAdminDocumentForm(props.token,props.id);file.value=form.value.fileMedia??null;original=file.value?.id??null}catch(e){error.value=e instanceof Error?e.message:'Не удалось открыть форму'}finally{loading.value=false}})
async function upload(e:Event){const selected=(e.target as HTMLInputElement).files?.[0];if(!selected)return;loading.value=true;try{const item=await uploadMedia(props.token,selected,form.value.title);uploaded.add(item.id);file.value=item;form.value.fileMediaId=item.id;form.value.displayFileType=selected.name.split('.').pop()?.toUpperCase()||'ФАЙЛ';form.value.displayFileSize=readable(item.sizeBytes)}catch(reason){error.value=reason instanceof Error?reason.message:'Не удалось загрузить файл'}finally{loading.value=false;if(input.value)input.value.value=''}}
async function cancel(){await Promise.allSettled([...uploaded].map(id=>deleteMedia(props.token,id)));emit('cancel')}
async function save(){if(!form.value.title.trim()||!file.value){error.value='Укажите название и загрузите файл';return};loading.value=true;try{await saveAdminDocumentForm(props.token,form.value);if(original&&original!==form.value.fileMediaId)await deleteMedia(props.token,original);uploaded.clear();emit('saved')}catch(e){error.value=e instanceof Error?e.message:'Не удалось сохранить документ'}finally{loading.value=false}}
</script>
<template><section class="form"><div class="heading"><div><p class="eyebrow">{{id?'Редактирование':'Новый документ'}}</p><h2>{{id?(form.title||'Документ'):'Добавить документ'}}</h2></div><Button label="Закрыть" text @click="cancel"/></div><p v-if="error" class="form-error">{{error}}</p><label>Название *<InputText v-model="form.title"/></label><label>Описание<Textarea v-model="form.description" rows="4" auto-resize/></label><div class="media"><div class="heading"><div><h3>Файл документа *</h3><p>При замене старый файл удаляется с диска после сохранения.</p></div><Button :label="file?'Заменить файл':'Загрузить файл'" :loading="loading" @click="input?.click()"/></div><input ref="input" hidden type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.odt,.ods,image/*" @change="upload"/><article v-if="file"><strong>{{form.displayFileType||file.mime}}</strong><span>{{form.displayFileSize||readable(file.sizeBytes)}}</span><a :href="file.url" target="_blank" rel="noopener">Открыть файл</a></article><p v-else class="empty">Файл пока не загружен.</p></div><div class="publish"><div><strong>Показывать на сайте</strong><small>{{form.isPublished?'Документ опубликован':'Сохранится как черновик'}}</small></div><ToggleSwitch v-model="form.isPublished"/></div><div class="actions"><Button :label="id?'Сохранить изменения':'Добавить документ'" :loading="loading" @click="save"/><Button label="Отмена" text @click="cancel"/></div></section></template>
<style scoped>.form{display:grid;gap:1.25rem}.heading,.publish{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.heading h2,.heading h3{margin:0}.heading p:not(.eyebrow){margin:.3rem 0;color:#647067}.form label{display:grid;gap:.4rem;font-weight:700}.media{border-top:1px solid #e6e2d9;padding-top:1.2rem}.media article,.empty{margin-top:1rem;padding:1rem;background:#f3f5f1;border-radius:10px;display:flex;gap:1rem;align-items:center}.media article a{margin-left:auto}.publish{align-items:center;padding:1rem;background:#e9f3ef;border-radius:12px}.publish div{display:grid}.actions{display:flex;gap:.5rem;border-top:1px solid #eee;padding-top:1rem}@media(max-width:650px){.heading{flex-direction:column}.media article{align-items:flex-start;flex-direction:column}.media article a{margin-left:0}}</style>
